'use strict';

const DEFAULT_DELIMITER = ',';
const DEFAULT_EOL = '\r\n';
const ALLOWED_EOLS = ['\r\n', '\n'];

function describe(value) {
  if (typeof value === 'string') return JSON.stringify(value);
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

function assertOptionsObject(options) {
  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError(`options must be an object; received ${describe(options)}`);
  }
}

function resolveDelimiter(delimiter) {
  if (delimiter === undefined) return DEFAULT_DELIMITER;
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError(
      `delimiter must be a single character other than '"', CR or LF; received ${describe(delimiter)}`,
    );
  }
  return delimiter;
}

function resolveBoolean(name, value) {
  if (value === undefined) return false;
  if (typeof value !== 'boolean') {
    throw new TypeError(`${name} must be a boolean; received ${describe(value)}`);
  }
  return value;
}

/**
 * Validates the options shared by `parse` and `createParser`. Keys that only
 * `stringify` reads (such as `eol`) are ignored, so one options object can be
 * passed to both sides of a round trip.
 */
function resolveParseOptions(options) {
  assertOptionsObject(options);
  return {
    delimiter: resolveDelimiter(options.delimiter),
    header: resolveBoolean('header', options.header),
    skipEmptyLines: resolveBoolean('skipEmptyLines', options.skipEmptyLines),
  };
}

/**
 * Validates `stringify` options. `header` is either absent/false or an array
 * of column-name strings; keys that only the parser reads are ignored.
 */
function resolveStringifyOptions(options) {
  assertOptionsObject(options);
  const delimiter = resolveDelimiter(options.delimiter);

  const eol = options.eol === undefined ? DEFAULT_EOL : options.eol;
  if (!ALLOWED_EOLS.includes(eol)) {
    throw new TypeError(`eol must be "\\r\\n" or "\\n"; received ${describe(options.eol)}`);
  }

  let header = null;
  if (Array.isArray(options.header)) {
    // An indexed loop, not forEach, so holes in a sparse array are rejected too.
    for (let index = 0; index < options.header.length; index++) {
      const name = options.header[index];
      if (typeof name !== 'string') {
        throw new TypeError(`header[${index}] must be a string; received ${describe(name)}`);
      }
    }
    header = options.header.slice();
  } else if (options.header !== undefined && options.header !== false) {
    throw new TypeError(
      `header must be an array of column names; received ${describe(options.header)}`,
    );
  }

  return { delimiter, eol, header };
}

module.exports = { resolveParseOptions, resolveStringifyOptions, describe };
'use strict';

/**
 * Thrown when CSV input is malformed. `line` and `column` are 1-based;
 * columns count UTF-16 code units. `code` identifies the kind of problem so
 * callers can branch without matching on the message.
 */
class CsvError extends Error {
  /**
   * @param {string} message
   * @param {number} line
   * @param {number} column
   * @param {'UNCLOSED_QUOTE'|'INVALID_AFTER_QUOTE'|'DUPLICATE_HEADER'|'FIELD_COUNT_MISMATCH'} code
   */
  constructor(message, line, column, code) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
    this.code = code;
  }
}

module.exports = { CsvError };
'use strict';

const { CsvError } = require('./errors');
const { resolveParseOptions, describe } = require('./options');

const QUOTE = 0x22;
const CR = 0x0d;
const LF = 0x0a;
const BOM = 0xfeff;

// FIELD_START: nothing of the current field has been consumed.
// AFTER_QUOTE: the previous code unit was a `"` inside a quoted field; it is
// either the closing quote or the first half of an escaped `""`.
const FIELD_START = 0;
const UNQUOTED = 1;
const QUOTED = 2;
const AFTER_QUOTE = 3;

/**
 * Incremental CSV state machine. Every code unit is examined exactly once, and
 * all state that must survive a chunk boundary (partial field, pending CR,
 * pending quote) lives on the instance, so the split points never change the
 * result. `parse` is this class fed a single chunk.
 */
class RecordReader {
  constructor(options) {
    const { delimiter, header, skipEmptyLines } = resolveParseOptions(options);
    this.delimiter = delimiter.charCodeAt(0);
    this.skipEmptyLines = skipEmptyLines;

    // In header mode, `seenNames` is non-null only while the header record is
    // being read, so duplicates are caught as soon as the repeated field ends.
    this.headerMode = header;
    this.headerNames = null;
    this.seenNames = header ? new Set() : null;

    this.state = FIELD_START;
    this.fields = [];
    this.parts = []; // pieces of the current field that ended a chunk or preceded a `""`
    this.segmentStart = 0; // chunk index where the not-yet-saved piece of the field begins
    this.recordEmpty = true; // no code unit of the current record consumed yet
    this.afterCR = false; // previous code unit was a CR, so an LF now completes a CRLF

    this.started = false;
    this.chunkOffset = 0; // absolute offset of the current chunk's first code unit
    this.line = 1;
    this.lineOffset = 0; // absolute offset of the current line's first code unit
    this.recordLine = 1;
    this.fieldLine = 1;
    this.fieldColumn = 1;
    this.quoteLine = 1;
    this.quoteColumn = 1;

    this.output = [];
  }

  column(index) {
    return this.chunkOffset + index - this.lineOffset + 1;
  }

  write(chunk) {
    const length = chunk.length;
    let index = 0;
    if (!this.started && length > 0) {
      this.started = true;
      if (chunk.charCodeAt(0) === BOM) {
        // The BOM is not part of the data, so column 1 is the code unit after it.
        index = 1;
        this.lineOffset = 1;
      }
    }

    while (index < length) {
      switch (this.state) {
        case FIELD_START:
          index = this.fieldStart(chunk, index);
          break;
        case UNQUOTED:
          index = this.unquoted(chunk, index);
          break;
        case QUOTED:
          index = this.quoted(chunk, index);
          break;
        default:
          index = this.afterQuote(chunk, index);
      }
    }

    if ((this.state === UNQUOTED || this.state === QUOTED) && this.segmentStart < length) {
      this.parts.push(chunk.slice(this.segmentStart));
    }
    this.segmentStart = 0;
    this.chunkOffset += length;
    return this.takeOutput();
  }

  end() {
    switch (this.state) {
      case QUOTED:
        throw new CsvError(
          'Quoted field is never closed',
          this.quoteLine,
          this.quoteColumn,
          'UNCLOSED_QUOTE',
        );
      case UNQUOTED:
      case AFTER_QUOTE:
        this.endField(this.joinParts());
        this.endRecord();
        break;
      default:
        // An empty pending record means the input was empty or ended with a
        // line break, which does not start another record.
        if (!this.recordEmpty) {
          this.endField('');
          this.endRecord();
        }
    }
    return this.takeOutput();
  }

  fieldStart(chunk, index) {
    const code = chunk.charCodeAt(index);
    if (this.afterCR) {
      this.afterCR = false;
      if (code === LF) {
        this.lineOffset = this.chunkOffset + index + 1;
        return index + 1;
      }
    }

    if (this.recordEmpty) {
      // Later fields get their start position from delimiterAt.
      this.recordLine = this.line;
      this.fieldLine = this.line;
      this.fieldColumn = this.column(index);
    }

    if (code === QUOTE) {
      this.recordEmpty = false;
      this.quoteLine = this.fieldLine;
      this.quoteColumn = this.fieldColumn;
      this.state = QUOTED;
      this.segmentStart = index + 1;
      return this.quoted(chunk, index + 1);
    }
    if (code === this.delimiter) {
      this.recordEmpty = false;
      this.endField('');
      this.delimiterAt(index);
      return index + 1;
    }
    if (code === CR || code === LF) {
      if (!this.recordEmpty || !this.skipEmptyLines) {
        this.endField('');
        this.endRecord();
      }
      this.recordBreak(code, index);
      return index + 1;
    }
    this.recordEmpty = false;
    this.state = UNQUOTED;
    this.segmentStart = index;
    return this.unquoted(chunk, index + 1);
  }

  unquoted(chunk, index) {
    const length = chunk.length;
    const delimiter = this.delimiter;
    for (; index < length; index++) {
      const code = chunk.charCodeAt(index);
      if (code === delimiter) {
        this.endField(this.takeValue(chunk, index));
        this.delimiterAt(index);
        return index + 1;
      }
      if (code === CR || code === LF) {
        this.endField(this.takeValue(chunk, index));
        this.endRecord();
        this.recordBreak(code, index);
        return index + 1;
      }
    }
    return index;
  }

  quoted(chunk, index) {
    const length = chunk.length;
    let afterCR = this.afterCR;
    for (; index < length; index++) {
      const code = chunk.charCodeAt(index);
      if (code === QUOTE) {
        if (index > this.segmentStart) this.parts.push(chunk.slice(this.segmentStart, index));
        this.afterCR = false;
        this.state = AFTER_QUOTE;
        return index + 1;
      }
      if (code === CR) {
        this.line++;
        this.lineOffset = this.chunkOffset + index + 1;
        afterCR = true;
      } else if (code === LF) {
        if (!afterCR) this.line++;
        this.lineOffset = this.chunkOffset + index + 1;
        afterCR = false;
      } else {
        afterCR = false;
      }
    }
    this.afterCR = afterCR;
    return index;
  }

  afterQuote(chunk, index) {
    const code = chunk.charCodeAt(index);
    if (code === QUOTE) {
      // Escaped quote: keep the second `"` as the first unit of the next piece.
      this.state = QUOTED;
      this.segmentStart = index;
      return this.quoted(chunk, index + 1);
    }
    if (code === this.delimiter) {
      this.endField(this.joinParts());
      this.delimiterAt(index);
      return index + 1;
    }
    if (code === CR || code === LF) {
      this.endField(this.joinParts());
      this.endRecord();
      this.recordBreak(code, index);
      return index + 1;
    }
    throw new CsvError(
      `Expected a delimiter, line break or end of input after a closing quote, found ${JSON.stringify(chunk[index])}`,
      this.line,
      this.column(index),
      'INVALID_AFTER_QUOTE',
    );
  }

  /**
   * Called after a delimiter at `index` ends a field. The next field starts
   * right after it, even when no code unit follows (a trailing delimiter).
   */
  delimiterAt(index) {
    this.state = FIELD_START;
    this.fieldLine = this.line;
    this.fieldColumn = this.column(index + 1);
  }

  /** Records a CR or LF (outside quotes) that has just ended a record. */
  recordBreak(code, index) {
    this.line++;
    this.lineOffset = this.chunkOffset + index + 1;
    this.afterCR = code === CR;
    this.state = FIELD_START;
  }

  takeValue(chunk, end) {
    const piece = chunk.slice(this.segmentStart, end);
    if (this.parts.length === 0) return piece;
    this.parts.push(piece);
    return this.joinParts();
  }

  joinParts() {
    const value = this.parts.length === 1 ? this.parts[0] : this.parts.join('');
    this.parts.length = 0;
    return value;
  }

  endField(value) {
    if (this.seenNames !== null) {
      if (this.seenNames.has(value)) {
        throw new CsvError(
          `Duplicate header name ${JSON.stringify(value)}`,
          this.fieldLine,
          this.fieldColumn,
          'DUPLICATE_HEADER',
        );
      }
      this.seenNames.add(value);
    }
    this.fields.push(value);
  }

  endRecord() {
    const fields = this.fields;
    this.fields = [];
    this.recordEmpty = true;

    if (!this.headerMode) {
      this.output.push(fields);
      return;
    }
    if (this.headerNames === null) {
      this.headerNames = fields;
      this.seenNames = null;
      return;
    }
    const names = this.headerNames;
    if (fields.length !== names.length) {
      throw new CsvError(
        `Expected ${names.length} field${names.length === 1 ? '' : 's'} to match the header, found ${fields.length}`,
        this.recordLine,
        1,
        'FIELD_COUNT_MISMATCH',
      );
    }
    this.output.push(toObject(names, fields));
  }

  takeOutput() {
    const records = this.output;
    this.output = [];
    return records;
  }
}

function toObject(names, fields) {
  const record = {};
  for (let k = 0; k < names.length; k++) {
    if (names[k] === '__proto__') {
      // Plain assignment would call the prototype setter and drop the value.
      Object.defineProperty(record, '__proto__', {
        value: fields[k],
        enumerable: true,
        writable: true,
        configurable: true,
      });
    } else {
      record[names[k]] = fields[k];
    }
  }
  return record;
}

/**
 * Parses a complete CSV string.
 *
 * @param {string} text
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {Array<string[]> | Array<Record<string, string>>} arrays of fields,
 *   or objects keyed by the first record when `header` is true
 * @throws {TypeError} if `text` is not a string or an option is invalid
 * @throws {CsvError} if the input is malformed
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`text must be a string; received ${describe(text)}`);
  }
  const reader = new RecordReader(options);
  const records = reader.write(text);
  for (const record of reader.end()) records.push(record);
  return records;
}

/**
 * Creates a parser for input that arrives in pieces. The records returned by
 * all `write` calls plus `end` equal `parse(chunks.join(''), options)`, and a
 * `CsvError` carries the same position, wherever the chunks are split.
 *
 * Once `end` returns or either method throws, both methods throw an `Error`.
 *
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {{write(chunk: string): Array<string[] | Record<string, string>>,
 *            end(): Array<string[] | Record<string, string>>}}
 * @throws {TypeError} if an option is invalid
 */
function createParser(options = {}) {
  const reader = new RecordReader(options);
  let ended = false;
  let failure = null;

  function run(method, operation) {
    if (failure !== null) {
      throw new Error(`Cannot call ${method}(): the parser already threw (${failure.message})`, {
        cause: failure,
      });
    }
    if (ended) throw new Error(`Cannot call ${method}(): the parser has already ended`);
    try {
      return operation();
    } catch (error) {
      failure = error;
      throw error;
    }
  }

  return {
    write(chunk) {
      return run('write', () => {
        if (typeof chunk !== 'string') {
          throw new TypeError(`chunk must be a string; received ${describe(chunk)}`);
        }
        return reader.write(chunk);
      });
    },
    end() {
      return run('end', () => {
        const records = reader.end();
        ended = true;
        return records;
      });
    },
  };
}

module.exports = { parse, createParser };
# csv-rfc4180

A CSV parser, streaming parser and serializer for Node.js with no dependencies.
It follows RFC 4180 and also accepts LF and CR line breaks, other delimiters,
and a leading byte order mark.

```js
const { parse, createParser, stringify, CsvError } = require('./src/csv');
```

Requires Node.js 18 or later. Run the tests with `npm test`.

## parse(text, options)

```js
parse('name,qty\r\n"Widget, large",3\r\n');
// [['name', 'qty'], ['Widget, large', '3']]

parse('name,qty\nWidget,3\n', { header: true });
// [{ name: 'Widget', qty: '3' }]

parse('a;b\n\n1;2', { delimiter: ';', skipEmptyLines: true });
// [['a', 'b'], ['1', '2']]
```

Options:

| option           | default | meaning                                                      |
| ---------------- | ------- | ------------------------------------------------------------ |
| `delimiter`      | `','`   | one character, not `"`, CR or LF                             |
| `header`         | `false` | use the first record as column names and return objects      |
| `skipEmptyLines` | `false` | drop lines with no characters instead of returning `['']`   |

Every field is a string, and whitespace is never trimmed. A field starting with
`"` is quoted: delimiters and line breaks inside it are literal, `""` is one
`"`, and the closing quote must be followed by a delimiter, a line break or the
end of input. A `"` anywhere else in an unquoted field is an ordinary character.

## createParser(options)

```js
const parser = createParser({ header: true });
parser.write('id,na');     // []
parser.write('me\n1,Ada'); // []  (the header record is not returned)
parser.write('\n2,Grace'); // [{ id: '1', name: 'Ada' }]
parser.end();              // [{ id: '2', name: 'Grace' }]
```

`write(chunk)` returns the records whose terminating line break is in `chunk`.
`end()` returns whatever is left. The combined output, and any `CsvError`
including its position, is the same as `parse` on the joined input, however
the input is split. After `end()` or after any throw, both methods throw an
`Error` whose `cause` is the original failure, if there was one.

Each code unit is read once. A field that spans chunks is kept as a list of
slices and joined when it ends, so memory and time grow with the input, not
with the number of `write` calls times the input.

## stringify(rows, options)

```js
stringify([['a', 'b c'], ['x,y', 'say "hi"']]);
// 'a,b c\r\n"x,y","say ""hi"""\r\n'

stringify([{ id: 1, name: 'Ada' }, { id: 2 }], { header: ['id', 'name'], eol: '\n' });
// 'id,name\n1,Ada\n2,\n'
```

| option      | default  | meaning                                                   |
| ----------- | -------- | --------------------------------------------------------- |
| `delimiter` | `','`    | same rules as `parse`                                     |
| `eol`       | `'\r\n'` | `'\r\n'` or `'\n'`; written after every record            |
| `header`    | none     | array of column names; allows object rows                 |

Strings are written as they are, numbers and booleans with `String()`, and
`null` and `undefined` as empty fields. Other types throw `TypeError`. A field
is quoted when it contains the delimiter, `"`, CR or LF, or begins or ends
with a space.

For rows that are non-empty arrays of strings, `parse(stringify(rows, opts),
opts)` returns `rows`, with or without `skipEmptyLines`. Each function ignores
options that only the other one reads, so the same object works for both.

## Errors

Malformed input throws `CsvError`, which extends `Error` and has 1-based
`line` and `column` properties (columns count UTF-16 code units) and a `code`:

| code                   | position reported                                    |
| ---------------------- | ---------------------------------------------------- |
| `UNCLOSED_QUOTE`       | the opening `"` of the field that is never closed    |
| `INVALID_AFTER_QUOTE`  | the character after the closing `"`                  |
| `DUPLICATE_HEADER`     | the start of the second field with that name         |
| `FIELD_COUNT_MISMATCH` | column 1 of the line where the bad record starts     |

CRLF counts as one line break, including inside quoted fields. When the input
has several problems, the first one found reading left to right is thrown. A
record's field count is checked when the record ends.

Invalid arguments (a non-string `text` or chunk, a bad delimiter, a non-boolean
`header`, an unsupported value type) throw `TypeError`.

## Decisions and assumptions

The specification left these points open. This is how they were resolved.

- **BOM and columns.** A leading U+FEFF is dropped before anything is counted,
  so the code unit after it is column 1. Only the first code unit of the whole
  input is checked, including when the first `write` chunks are empty.
- **Delimiter width.** "A single character" means one UTF-16 code unit
  (`delimiter.length === 1`). A character outside the Basic Multilingual Plane,
  such as an emoji, is rejected with `TypeError`.
- **What `skipEmptyLines` skips.** Only lines with no characters at all. A line
  holding `""` is a record with one empty field and is kept, which is what lets
  `stringify` preserve `['']` through a round trip.
- **Empty lines in header mode.** Without `skipEmptyLines`, an empty line is
  the record `['']`, so it is a field-count error unless the header has exactly
  one column. An empty first line becomes a header with one column named `''`.
- **When duplicates are detected.** A duplicate header name is reported when
  the repeated field ends, because that is the point where a single
  left-to-right read can know the name. So `a,a,"x` reports the duplicate, not
  the unclosed quote.
- **Record objects.** Rows are plain objects with one own property per column,
  in header order. A column named `__proto__` is stored as an ordinary property
  rather than changing the prototype. JavaScript lists integer-like keys such
  as `"1"` before other keys no matter where they appear in the header.
- **Streaming and CRLF.** A record ending in CRLF is returned by the `write`
  that contains the CR. If the next chunk starts with LF, that LF is treated
  as the second half of the same line break.
- **Option validation.** `options` must be an object. `header` and
  `skipEmptyLines` for parsing must be booleans when given. For `stringify`,
  `header` must be an array of strings (or omitted/`false`). Unknown keys are
  ignored.
- **Header with no rows.** `stringify([], { header: ['a', 'b'] })` writes the
  header line, `'a,b\r\n'`. "No rows gives `''`" applies when there is no
  header either.
- **Object rows.** Only own properties are read, so a column named `toString`
  is empty for `{}` instead of picking up `Object.prototype.toString`. Array
  rows are still accepted when `header` is set and are written unchanged.
- **Lone empty field.** A record whose only field is empty (`['']`, `[null]` or
  `[undefined]`) is written as `""`. A record with no fields (`[]`) is written
  as an empty line.
- **Leading U+FEFF in output.** If the first line of the output would start
  with U+FEFF (a first field beginning with it, or an empty first field when
  U+FEFF is the delimiter), that field is quoted. Otherwise the parser would
  take it for a byte order mark and the round trip would lose it.
- **Duplicate names in `stringify`'s header** are not rejected. The output is
  valid CSV, but `parse` with `header: true` will refuse it.

## Layout

| file                | contents                                          |
| ------------------- | ------------------------------------------------- |
| `src/csv.js`        | public entry point                                |
| `src/parser.js`     | state machine behind `parse` and `createParser`   |
| `src/stringify.js`  | serializer                                        |
| `src/options.js`    | option validation shared by both directions       |
| `src/errors.js`     | `CsvError`                                        |

