'use strict';

const DEFAULT_DELIMITER = ',';
const DEFAULT_EOL = '\r\n';
const ALLOWED_EOLS = ['\r\n', '\n'];

function describe(value) {
  if (typeof value === 'string') return JSON.stringify(value);
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

function assertOptionsObject(options) {
  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError(`options must be an object; received ${describe(options)}`);
  }
}

function resolveDelimiter(delimiter) {
  if (delimiter === undefined) return DEFAULT_DELIMITER;
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError(
      `delimiter must be a single character other than '"', CR or LF; received ${describe(delimiter)}`,
    );
  }
  return delimiter;
}

function resolveBoolean(name, value) {
  if (value === undefined) return false;
  if (typeof value !== 'boolean') {
    throw new TypeError(`${name} must be a boolean; received ${describe(value)}`);
  }
  return value;
}

/**
 * Validates the options shared by `parse` and `createParser`. Keys that only
 * `stringify` reads (such as `eol`) are ignored, so one options object can be
 * passed to both sides of a round trip.
 */
function resolveParseOptions(options) {
  assertOptionsObject(options);
  return {
    delimiter: resolveDelimiter(options.delimiter),
    header: resolveBoolean('header', options.header),
    skipEmptyLines: resolveBoolean('skipEmptyLines', options.skipEmptyLines),
  };
}

/**
 * Validates `stringify` options. `header` is either absent/false or an array
 * of column-name strings; keys that only the parser reads are ignored.
 */
function resolveStringifyOptions(options) {
  assertOptionsObject(options);
  const delimiter = resolveDelimiter(options.delimiter);

  const eol = options.eol === undefined ? DEFAULT_EOL : options.eol;
  if (!ALLOWED_EOLS.includes(eol)) {
    throw new TypeError(`eol must be "\\r\\n" or "\\n"; received ${describe(options.eol)}`);
  }

  let header = null;
  if (Array.isArray(options.header)) {
