    assert.deepEqual(parse('a\n#x\n\nb', { ...opts, skipEmptyLines: true }), [['a'], ['b']]);
  });

  it('treats the comment character elsewhere as ordinary', () => {
    assert.deepEqual(parse('a#b,#c\n ,#d\n"#e",f#', opts), [['a#b', '#c'], [' ', '#d'], ['#e', 'f#']]);
  });

  it('only recognises the character as the first of a line', () => {
    assert.deepEqual(parse(' #a\nb', { ...opts, trim: true }), [['#a'], ['b']]);
    assert.deepEqual(parse('"a\n#b",c\n#d', opts), [['a\n#b', 'c']]);
  });

  it('applies after a BOM', () => {
    assert.deepEqual(parse('\uFEFF#x\na', opts), [['a']]);
  });

  it('skips the comment line before the header in header mode', () => {
    assert.deepEqual(parse('#c\na,b\n#d\n1,2\n', { ...opts, header: true }), [{ a: '1', b: '2' }]);
  });

  it('ignores delimiters and quotes inside a comment line', () => {
    assert.deepEqual(parse('#a,"b\nc', opts), [['c']]);
  });

  it('can be a blank character, which is then checked before trim', () => {
    assert.deepEqual(parse(' x\n y\nz', { comment: ' ', trim: true }), [['z']]);
  });

  it('counts comment lines in error positions', () => {
    expectCsvError('#a\r\n#b\n"x"y', opts, { line: 3, column: 4, code: 'INVALID_AFTER_QUOTE' });
    expectCsvError('#a\n#b\n"x', opts, { line: 3, column: 1, code: 'UNCLOSED_QUOTE' });
    expectCsvError('#a\nh,h', { ...opts, header: true }, { line: 2, column: 3, code: 'DUPLICATE_HEADER' });
    expectCsvError('a,b\n#c\n#d\n1', { ...opts, header: true }, { line: 4, column: 1, code: 'FIELD_COUNT_MISMATCH' });
  });

  it('counts a CR comment break followed by LF as one break', () => {
    expectCsvError('#a\r\n"x"y', opts, { line: 2, column: 4, code: 'INVALID_AFTER_QUOTE' });
  });

  it('must be one character other than the delimiter, quote, CR and LF', () => {
    for (const comment of ['', '##', '"', '\r', '\n', ',', 1, null, true, {}, '\u{1F600}']) {
      assert.throws(() => parse('a', { comment }), TypeError, JSON.stringify(comment));
      assert.throws(() => createParser({ comment }), TypeError, JSON.stringify(comment));
    }
    assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
    assert.deepEqual(parse('#a;b', { comment: ';', delimiter: '|' }), [['#a;b']]);
    assert.deepEqual(parse(';x\na', { comment: ';' }), [['a']]);
  });
});

describe('trim and comment in createParser', () => {
  const CORPUS = [
    '',
    ' a , "b" ,c ',
    '\t"a b" \t,\t x\t\r\n  \r\n',
    '  "a\r\nb"  ,  c  \n',
    '"a" x',
    '"a"  "b"',
    '  "unclosed',
    '"a"  ',
    '   ',
    'a,  ',
    '#c\na,b\r\n#d\r\n1,2\r#e\n3,4',
    '#c\r\n#d\r',
    '#only',
    'a#b,#c\n #d\n"#e"\n',
    '\uFEFF#x\n\uFEFF  a\n',
    '#c,"\n"q"r',
    'h,h\n',
    '#c\nh, h\n',
    'a,b\n#c\n 1 \n',
    ' #x\n#y  \n  z',
  ];

  const OPTION_SETS = [
    { trim: true },
    { comment: '#' },
    { trim: true, comment: '#' },
    { trim: true, comment: '#', header: true },
    { trim: true, comment: '#', skipEmptyLines: true },
    { trim: true, delimiter: '\t' },
    { trim: true, comment: ' ' },
  ];

  for (const options of OPTION_SETS) {
    it(`matches parse for every split with options ${JSON.stringify(options)}`, () => {
      for (const text of CORPUS) {
        const expected = outcomeOfParse(text, options);
        for (const chunks of splits(text)) {
          assert.deepEqual(
            outcomeOfChunks(chunks, options),
            expected,
            `input ${JSON.stringify(text)} split as ${JSON.stringify(chunks)}`,
          );
        }
      }
    });
  }

  it('returns a trimmed field only once its end is known', () => {
    const parser = createParser({ trim: true });
    assert.deepEqual(parser.write('  a '), []);
    assert.deepEqual(parser.write(' \t'), []);
    assert.deepEqual(parser.write(' b\n'), [['a  \t b']]);
    assert.deepEqual(parser.end(), []);
  });

  it('skips a comment line spread over chunks, including a split CRLF', () => {
    const parser = createParser({ comment: '#' });
    assert.deepEqual(parser.write('#ab'), []);
    assert.deepEqual(parser.write('c\r'), []);
    assert.deepEqual(parser.write('\nx\n'), [['x']]);
    assert.deepEqual(parser.end(), []);
  });
});
